import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { splitBlocks, splitLineBlocks, splitLines } from "../src/phizziwig/blocks";

// Generated by scripts/generate-block-fixtures.mjs from the PHP engine.
const fixtures: { text: string; blocks: [number, number][] }[] = JSON.parse(
  readFileSync(new URL("fixtures/blocks.json", import.meta.url), "utf8"),
);

describe("splitLineBlocks", () => {
  it("splits like Phorge's remarkup engine", () => {
    // A broken generation must not make this pass on nothing.
    expect(fixtures.length).toBeGreaterThan(1000);
    const mismatches = fixtures.filter(({ text, blocks }) => {
      const actual = splitLineBlocks(splitLines(text)).map((b) => [b.start, b.numLines]);
      return JSON.stringify(actual) !== JSON.stringify(blocks);
    });
    expect(mismatches.slice(0, 3)).toEqual([]);
  });
});

describe("splitBlocks", () => {
  it("covers the text and excludes trailing blank lines from the content", () => {
    const text = "= Title =\n\n\nPara\ngraph\n\n| a |\n";
    const blocks = splitBlocks(text);
    expect(blocks.map((b) => [b.kind, text.slice(b.from, b.contentTo)])).toEqual([
      ["header", "= Title ="],
      ["paragraph", "Para\ngraph"],
      ["table", "| a |"],
    ]);
    expect(blocks.map((b) => text.slice(b.from, b.to)).join("")).toBe(text);
  });
});
